acceptanceScript:
import assert from 'node:assert/strict';
import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {Client} from '/Users/greyson/DevProjects/forge/node_modules/@modelcontextprotocol/client';
import {InMemoryTransport} from '/Users/greyson/DevProjects/forge/node_modules/@modelcontextprotocol/server';
import {createMcpToolContext,createForgeMcpServerFromContext} from '/Users/greyson/DevProjects/forge/adapters/mcp/server';
import {ensureControllerHome} from '/Users/greyson/DevProjects/forge/src/effects/controller-home';
import {registerRepository} from '/Users/greyson/DevProjects/forge/src/cli/repositories/registry';
import {getEditSession} from '/Users/greyson/DevProjects/forge/src/cli/editing/edit-session';
import {listWorkContracts} from '/Users/greyson/DevProjects/forge/src/runtime/control-plane/facade/work-contract-store';
import {waitForProcess} from '/Users/greyson/DevProjects/forge/src/runtime/execution/process-runtime/runtime';
const root=import.meta.dir,home=join(root,'controller-fixed'),repo=join(root,'repo-fixed');
process.env.FORGE_CONTROLLER_HOME=home;
mkdirSync(join(repo,'.forge'),{recursive:true});
function git(...args:string[]){const r=spawnSync('git',args,{cwd:repo,encoding:'utf8'});assert.equal(r.status,0,r.stderr);}
git('init','-q','-b','main');git('config','user.name','Acceptance');git('config','user.email','acceptance@example.test');
writeFileSync(join(repo,'source.ts'),'export const n = 1;\n');
writeFileSync(join(repo,'.forge/checks.json'),JSON.stringify({version:1,checks:{verify:{description:'real source bytes',command:[process.execPath,'-e',`const fs=require('fs');if(fs.readFileSync('source.ts','utf8')!=='export const n = 3;'+String.fromCharCode(10))process.exit(1);`],timeoutMs:10000,effects:{reads:['source.ts']}}}}));
git('add','.');git('commit','-qm','acceptance fixture');ensureControllerHome(home);
const repository=registerRepository({path:repo,controllerHome:home,displayName:'475 MCP acceptance'});
const events:any[]=[];
async function connect(sessionId:string){
 const ctx=createMcpToolContext({controllerHome:home,profile:'controller',repo,principalId:'acceptance-controller',sessionId});
 const server=createForgeMcpServerFromContext(ctx);const [a,b]=InMemoryTransport.createLinkedPair();await server.connect(b);
 const client=new Client({name:'475-acceptance',version:'1.0.0'},{capabilities:{}});await client.connect(a);return {client,server};
}
let pair=await connect('before-reconnect');
async function call(name:string,args:any){const start=Date.now();const r:any=await pair.client.callTool({name,arguments:{repo_id:repository.repoId,...args}});const payload=r.structuredContent??JSON.parse(r.content.find((x:any)=>x.type==='text').text);events.push({name,requestId:args.request_id,ms:Date.now()-start,isError:r.isError??false,payload});assert.notEqual(r.isError,true,JSON.stringify(payload));return payload;}
async function verify(id:string,request:string){let v=await call('verify_edit_session',{session_id:id,check_ids:['verify'],request_id:request});for(const p of v.processes??[])await waitForProcess(home,repository.repoId,p.processId,{timeoutMs:10000});if(!v.completed)v=await call('verify_edit_session',{session_id:id,check_ids:['verify'],request_id:request});return v;}
const session=await call('begin_edit_session',{purpose:'same session repairs failed source check across MCP reconnect',allowed_paths:['source.ts'],checks:['verify']});
const sha=(s:string)=>createHash('sha256').update(s).digest('hex');
await call('apply_patch',{session_id:session.sessionId,expected_revision:0,operations:[{type:'replace',path:'source.ts',expected_sha256:sha(readFileSync(join(repo,'source.ts'),'utf8')),replacements:[{old_text:'n = 1',new_text:'n = 2'}]}]});
const failed=await verify(session.sessionId,'475-fail-r1');assert.equal(failed.ok,false);assert.equal(getEditSession(repo,session.sessionId).status,'check_failed');
await pair.client.close();await pair.server.close();pair=await connect('after-reconnect');
await call('apply_patch',{session_id:session.sessionId,expected_revision:1,operations:[{type:'replace',path:'source.ts',expected_sha256:sha(readFileSync(join(repo,'source.ts'),'utf8')),replacements:[{old_text:'n = 2',new_text:'n = 3'}]}]});
const passed=await verify(session.sessionId,'475-pass-r2');assert.equal(passed.ok,true);assert.equal(passed.editRevision,2);
const closed=await call('finalize_edit_session',{session_id:session.sessionId,reviewer:'isolated MCP acceptance'});assert.equal(closed.status,'finalized');assert.equal(listWorkContracts({controllerHome:home,repoId:repository.repoId}).length,0);
await pair.client.close();await pair.server.close();
writeFileSync(join(root,'receipt.json'),JSON.stringify({sourceBase:'fb75fbbb7e3d2db99b4bbdb9ac64e8032becb575',sessionId:session.sessionId,revisions:2,worksCreated:0,failedCheck:failed.ok,passedCheck:passed.ok,finalStatus:closed.status,reconnected:true,events},null,2));
console.log('ACCEPT: MCP begin → patch → failed check → reconnect → patch → passed check → finalize; same Session, two revisions, zero Work');
